# extract_receipt_fields.py\n# [SAME-SCENARIO] extracts merchant, tax, total, and items from a receipt\n\nfrom document_client import DocumentClient\nfrom document_models import ReceiptExtractionRequest, ReceiptExtractionResponse\n\n# Using Document AI Invoice Parser (generic OCR) as the concrete provider\n# Required environment variable: GOOGLE_APPLICATION_CREDENTIALS\n\ndef extract_receipt_fields(file_path: str) -> ReceiptExtractionResponse:\n    # Initialize client with Document AI SDK\n    client = DocumentClient(service="DocumentAI", api_key="${GOOGLE_APPLICATION_CREDENTIALS}")\n    # Create request payload\n    request = ReceiptExtractionRequest(\n        file_path=file_path,\n        document_type="receipt"\n    )\n    # Call Document AI OCR endpoint (via SDK wrapper)\n    response_data = client.process_document(request)\n    # Map response to standard response model\n    return response_data\n
